import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Nextjs","description":"Nextjs reference documentation","frontmatter":{"title":"Nextjs","description":"Nextjs reference documentation"},"headers":[],"relativePath":"knowledge/nextjs.md","filePath":"knowledge/nextjs.md","lastUpdated":1784485118000}'),r={name:"knowledge/nextjs.md"};function s(i,e,c,d,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="nextjs" tabindex="-1">Nextjs <a class="header-anchor" href="#nextjs" aria-label="Permalink to &quot;Nextjs&quot;">​</a></h1><h1 id="next-js-app-router-—-knowledge-reference" tabindex="-1">Next.js App Router — Knowledge Reference <a class="header-anchor" href="#next-js-app-router-—-knowledge-reference" aria-label="Permalink to &quot;Next.js App Router — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Comprehensive reference for Next.js 14+ App Router development, covering server/client component architecture, data fetching patterns, routing conventions, and deployment optimization. This guide targets production applications using the App Router paradigm.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="app-router-architecture" tabindex="-1">App Router Architecture <a class="header-anchor" href="#app-router-architecture" aria-label="Permalink to &quot;App Router Architecture&quot;">​</a></h3><p>The App Router uses a file-system based router built on React Server Components. Every folder under <code>src/app/</code> becomes a route segment. The special <code>layout.tsx</code>, <code>page.tsx</code>, <code>loading.tsx</code>, <code>error.tsx</code>, and <code>not-found.tsx</code> files define route behavior.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/app/</span></span>
<span class="line"><span>├── layout.tsx          # Root layout (required)</span></span>
<span class="line"><span>├── page.tsx            # Home page (/)</span></span>
<span class="line"><span>├── about/</span></span>
<span class="line"><span>│   └── page.tsx        # /about</span></span>
<span class="line"><span>├── dashboard/</span></span>
<span class="line"><span>│   ├── layout.tsx      # Dashboard layout</span></span>
<span class="line"><span>│   ├── page.tsx        # /dashboard</span></span>
<span class="line"><span>│   └── settings/</span></span>
<span class="line"><span>│       └── page.tsx    # /dashboard/settings</span></span>
<span class="line"><span>└── api/</span></span>
<span class="line"><span>    └── users/</span></span>
<span class="line"><span>        └── route.ts    # API route</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="server-components-default" tabindex="-1">Server Components (Default) <a class="header-anchor" href="#server-components-default" aria-label="Permalink to &quot;Server Components (Default)&quot;">​</a></h3><p>All components in the App Router are Server Components by default. They execute on the server, have zero client-side JavaScript, and can directly access databases, file systems, and backend services.</p><h3 id="client-components" tabindex="-1">Client Components <a class="header-anchor" href="#client-components" aria-label="Permalink to &quot;Client Components&quot;">​</a></h3><p>Mark components with <code>&#39;use client&#39;</code> directive at the top of the file. Client Components are pre-rendered on the server (SSR) and then hydrated on the client. They support <code>useState</code>, <code>useEffect</code>, event handlers, and browser APIs.</p><h3 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h3><p>Layouts wrap pages and persist across navigations. They do not re-render on route changes. Nested layouts compose hierarchically — each <code>layout.tsx</code> receives <code>children</code> and its own <code>params</code>.</p><h3 id="data-fetching" tabindex="-1">Data Fetching <a class="header-anchor" href="#data-fetching" aria-label="Permalink to &quot;Data Fetching&quot;">​</a></h3><p>Native <code>fetch()</code> in Server Components is automatically deduplicated and cached. Use <code>cache: &#39;force-cache&#39;</code> (static) or <code>cache: &#39;no-store&#39;</code> (dynamic) to control behavior. Route Segment Config (<code>export const dynamic = &#39;force-dynamic&#39;</code>) overrides per-route.</p><h3 id="server-actions" tabindex="-1">Server Actions <a class="header-anchor" href="#server-actions" aria-label="Permalink to &quot;Server Actions&quot;">​</a></h3><p>Server Actions are async functions marked with <code>&#39;use server&#39;</code> that run on the server. They can be called from Client Components via form submissions or event handlers. They return plain serializable data.</p><h3 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;Middleware&quot;">​</a></h3><p>Middleware runs before a request is completed. Place <code>middleware.ts</code> at the project root. It can modify the request <code>NextResponse</code>, rewrite URLs, redirect, set headers, and read cookies/headers.</p><h3 id="metadata-api" tabindex="-1">Metadata API <a class="header-anchor" href="#metadata-api" aria-label="Permalink to &quot;Metadata API&quot;">​</a></h3><p>Export a <code>metadata</code> object or <code>generateMetadata</code> function from <code>layout.tsx</code> or <code>page.tsx</code>. Supports static metadata, dynamic metadata via functions, and parent metadata inheritance via <code>generateMetadata</code>.</p><h3 id="caching-strategies" tabindex="-1">Caching Strategies <a class="header-anchor" href="#caching-strategies" aria-label="Permalink to &quot;Caching Strategies&quot;">​</a></h3><ul><li><strong>Static Rendering</strong>: Content generated at build time, served from CDN</li><li><strong>Dynamic Rendering</strong>: Content generated at request time</li><li><strong>ISR (Incremental Static Regeneration)</strong>: <code>revalidate</code> option on <code>fetch</code> or route segment</li><li><strong>Streaming</strong>: <code>loading.tsx</code> + <code>Suspense</code> for progressive rendering</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Keep Server Components as the default</strong> — only add <code>&#39;use client&#39;</code> when you need interactivity, browser APIs, or React hooks that require client state</li><li><strong>Push Client Components to leaf nodes</strong> — create small interactive components and compose them inside Server Components rather than making entire pages client-rendered</li><li><strong>Use parallel routes for complex layouts</strong> — <code>@slot</code> routes allow independent loading states and error boundaries for split-view UIs</li><li><strong>Colocate data fetching with components</strong> — fetch data in the component that needs it, not in parent layouts unless shared</li><li><strong>Use <code>React.cache()</code> for request-level deduplication</strong> — when the same data is needed in multiple Server Components during a single request</li><li><strong>Define TypeScript types for params and searchParams</strong> — always type <code>params: { slug: string }</code> and <code>searchParams: { [key: string]: string | string[] | undefined }</code></li><li><strong>Use <code>next/image</code> for all images</strong> — it handles lazy loading, responsive sizing, format conversion, and prevents layout shift</li><li><strong>Prefer Route Handlers over API routes for external consumers</strong> — keep data fetching in Server Components for internal use, use Route Handlers for public APIs</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Making entire layout files client components</strong> — layouts should be Server Components; extract interactive sections into child Client Components</li><li><strong>Passing non-serializable props to Server Components</strong> — no functions, classes, or Date objects across server/client boundary</li><li><strong>Using <code>useRouter</code> in Server Components</strong> — use <code>redirect()</code> from <code>next/navigation</code> instead</li><li><strong>Fetching data in <code>useEffect</code> for initial loads</strong> — use Server Components for initial data; reserve <code>useEffect</code> for client-only updates</li><li><strong>Ignoring the hydration boundary</strong> — when mixing server and client, ensure the client component tree is properly bounded with <code>&#39;use client&#39;</code></li><li><strong>Using <code>force-dynamic</code> as a blanket solution</strong> — this disables all caching; be specific with per-fetch options instead</li><li><strong>Writing large Server Actions as monoliths</strong> — decompose into focused actions with clear input/output contracts</li><li><strong>Overusing <code>next/dynamic</code> without fallbacks</strong> — always provide <code>loading</code> or <code>ssr: false</code> for dynamic imports</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Forgetting <code>&#39;use client&#39;</code> on components using hooks</strong> — runtime error when a client-only hook runs in a Server Component</li><li><strong>Passing async functions as props</strong> — Server Components can be async, but their children receiving async props cannot serialize them</li><li><strong>Using <code>window</code>/<code>document</code> in Server Components</strong> — these are browser-only globals; guard with <code>typeof window !== &#39;undefined&#39;</code> or keep in Client Components</li><li><strong>Not typing route params</strong> — <code>params</code> comes as <code>Promise&lt;{}&gt;</code> in Next.js 15+; always await and type explicitly</li><li><strong>Mutating URL state without <code>useRouter</code></strong> — use <code>router.push()</code> or <code>router.replace()</code> for navigation, not direct URL manipulation</li><li><strong>Ignoring <code>Suspense</code> boundaries for streaming</strong> — without them, the entire page blocks on slow data fetches</li><li><strong>Hardcoding environment variables</strong> — use <code>NEXT_PUBLIC_</code> prefix for client-exposed vars, server-only for secrets</li><li><strong>Not using <code>loading.tsx</code> for slow routes</strong> — users see a blank screen during slow navigations without loading states</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>Needs <code>useState</code>/<code>useEffect</code></td><td>Client Component</td></tr><tr><td>Accesses database directly</td><td>Server Component</td></tr><tr><td>Handles user interaction</td><td>Client Component</td></tr><tr><td>Shared layout with persistence</td><td>Layout (Server)</td></tr><tr><td>One-time data fetch</td><td>Page-level Server Component</td></tr><tr><td>Real-time updates (WebSocket)</td><td>Client Component</td></tr><tr><td>SEO-critical content</td><td>Server Component + Metadata API</td></tr><tr><td>Form with server mutation</td><td>Server Action + Client form</td></tr><tr><td>Progressive loading</td><td><code>Suspense</code> + <code>loading.tsx</code></td></tr><tr><td>Conditional client/server rendering</td><td>Compose Server parent → Client children</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://nextjs.org/docs/app" target="_blank" rel="noreferrer">Next.js App Router Documentation</a></li><li><a href="https://github.com/reactjs/rfcs/pull/188" target="_blank" rel="noreferrer">React Server Components RFC</a></li><li><a href="https://nextjs.org/docs/app/building-your-application/data-fetching" target="_blank" rel="noreferrer">Next.js Data Fetching</a></li><li><a href="https://nextjs.org/docs/app/building-your-application/data-fetching/server-actions-and-mutations" target="_blank" rel="noreferrer">Server Actions Reference</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li>Server Components cannot be tested with standard React Testing Library — test the Server Component&#39;s output through integration tests or extract logic into testable utility functions</li><li>Layouts do not receive <code>searchParams</code> in Next.js 15+; pass them through <code>children</code> props if needed</li><li>When deploying to Vercel, ISR revalidation happens at the edge; self-hosted requires a CDN or polling strategy</li><li>Use <code>after()</code> API (Next.js 15+) for non-blocking post-response work like analytics and logging</li><li>Cache invalidation uses <code>revalidateTag()</code> and <code>revalidatePath()</code> — tag your fetches for granular control</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,38)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
